-- Height at a world position, or MapTerrain.Water.
function MapTerrain.At(x, z)
	local step = (MapTerrain.HalfSize * 2) / MapTerrain.Size
	local gx = math.clamp(math.floor((x + MapTerrain.HalfSize) / step) + 1, 1, MapTerrain.Size)
	local gz = math.clamp(math.floor((z + MapTerrain.HalfSize) / step) + 1, 1, MapTerrain.Size)
	local row = MapTerrain.Heights[gz]
	return row and row[gx] or MapTerrain.Water
end

-- The material letter for a cell, by grid index.
function MapTerrain.MaterialAt(gx, gz)
	local row = MapTerrain.Materials[gz]
	return row and row:sub(gx, gx) or "w"
end

return MapTerrain
